import {foliageAt} from './foliage-data.js';
import {TREE_COVER,treeCoverSelection} from './foliage-tree-cover.js';
import {EditorCharacterMenu} from './editor-character-menu.js';
import {EditorSpotlightMenu} from './editor-spotlight-menu.js';
import {installSectorSave} from './editor-sector-save.js';
import {installSectorPresets} from './editor-sector-presets.js';
import {loadPreset,presetSearch} from './sector-presets.js';
import {blockCanvas,extractBlock} from './core/blocks.js';
import {blankMap} from './core/maps.js';
import {PREVIEW_FOOTPRINTS} from './editor-3d-model.js';
import {EditingDocument} from './editor-3d-controller.js';
import {installEditing} from './editor-3d-tools.js';
import {InspectionScene} from './editor-3d-scene.js';
import {rotateInspectionView} from './editor-3d-camera.js';
const $=id=>document.getElementById(id),canvas=$('scene');
let documentModel,dirty=true,loading=false,serial=0,selection=null,drag=null,tools,characterMenu,spotlightMenu;
const workspaces={};
const view={x:11.5,y:11.5,span:24,preset:'0'};
const scene=new InspectionScene(canvas,()=>{dirty=true;diagnostics();});
const status=text=>$('status').textContent=text;
function diagnostics(){$('diagnostics').textContent=scene.diagnostics.join('\n')||'No missing scene assets reported.';$('metrics').textContent=`${scene.models.length} modeled starts · load ${Math.round(scene.loadMs||0)} ms · scenery ${Math.round(scene.rebuildMs||0)} ms · ${scene.renderer.info.memory.geometries} geometries / ${scene.renderer.info.memory.textures} textures`;}
function render(){if(dirty||scene.biomes.cutaway.active||scene.biomes.hedges.cutaway.active||scene.lights?.animated||(scene.sceneryAssets?.animated&&!scene.reducedMotion?.matches)){scene.draw(view,canvas.clientWidth,canvas.clientHeight);dirty=false;diagnostics();}characterMenu?.draw();spotlightMenu?.draw();requestAnimationFrame(render);}
function focus(x,y,span=24){view.x=x;view.y=y;view.span=span;dirty=true;}
function home(){view.preset='0';view.topTurn=0;$('camera').value='0';const p=documentModel?.map.starts[0];focus(p?.x??11.5,p?.y??11.5,22);}
async function open(text){
 const next=text instanceof EditingDocument?text:new EditingDocument().open(text),ticket=++serial;characterMenu?.reset();spotlightMenu?.reset();documentModel=next;workspaces[next.block?'block':'map']=next;loading=true;selection=null;scene.preview(null);$('properties').textContent='';$('selected').textContent='Choose a cell or object.';$('visual-note').textContent='';
 $('name').textContent=next.map.name;$('counts').textContent=`${next.size} × ${next.size} · ${next.block?'Block':next.map.guards.length+' placed characters'} · ${next.map.props.length} objects · ${next.map.canopies?.length||0} decorative roofs`;
 $('quick-save-map').title=next.map.sectorTemplate?.id&&!next.block?'Save as a new sector variant':'Save this design';$('save-sector-variant').disabled=next.block||!next.map.sectorTemplate?.id;
 const startLevel=next.block?0:next.map.starts[0]?.z||0;$('floor').value=String(startLevel);scene.options.level=startLevel;$('sector-x').max=$('sector-y').max=next.block?1:10;$('sector-x').value=$('sector-y').value='1';home();status('Loading modeled scenery and starts…');$('export').disabled=false;
 await scene.open(next);if(ticket!==serial)return;loading=false;tools.reset();$('floor').dispatchEvent(new Event('change'));status(scene.diagnostics.length?'Some visuals are unavailable. See scene diagnostics.':next.block?'Edit this reusable block, then save it to the library.':'Select a build tool to edit. Right-drag or WASD pans.');dirty=true;
}
async function factory(){try{status('Opening authored factory…');const r=await fetch('./default-factory.json',{cache:'no-store'});if(!r.ok)throw Error('Factory could not load: HTTP '+r.status);await open(await r.text());}catch(e){status(e.message);}}
function inspect(x,y){const p=scene.pick(x,y,canvas.clientWidth,canvas.clientHeight);if(!p||!documentModel)return null;return documentModel.inspect(p.x,p.y,scene.options.level,{...scene.options,mode:$('pick-mode').value});}
function select(value){selection=value;scene.select(value);$('selected').textContent=value?`${value.label} · ${value.x}, ${value.y} · floor ${value.z+1}`:'Choose a cell or object.';$('properties').textContent=value&&value.type!=='unit'?JSON.stringify(value.data,null,2):'';tools.selectionChanged();characterMenu?.selectionChanged();spotlightMenu?.selectionChanged();
 const notes=[];if(value?.type==='unit'){if(value.data.species==='hen'&&value.data.weapon!=='hands')notes.push('Saved weapon: '+value.data.weapon+'. The hen model currently has no armed pose.');if(value.data.id.startsWith('start'))notes.push('Squad start marker. Species and rifle are illustrative.');}$('visual-note').textContent=notes.join(' ');
}
$('factory').onclick=()=>{if(tools.guardReplace())factory();};$('home').onclick=home;$('overview').onclick=()=>{const size=documentModel?.size||240;focus((size-1)/2,(size-1)/2,size*1.55);};
$('camera').onchange=()=>{view.preset=$('camera').value;dirty=true;};
$('floor').onchange=()=>{scene.setOptions({level:+$('floor').value});select(null);};
$('show-all-levels').onchange=()=>{scene.setOptions({showAllLevels:$('show-all-levels').checked});select(null);};
for(const name of ['roofs','walls'])$(name).onchange=()=>{scene.setOptions({[name]:$(name).checked});select(null);};
$('sector').onclick=()=>{const max=documentModel?.block?1:10,x=+$('sector-x').value,y=+$('sector-y').value;if(!Number.isInteger(x)||!Number.isInteger(y)||x<1||x>max||y<1||y>max){status('Choose a sector column and row from 1 to '+max+'.');return;}focus((x-1)*24+11.5,(y-1)*24+11.5,28);};
const zoom=factor=>{view.span=Math.max(6,Math.min(450,view.span*factor));dirty=true;};$('zoom-in').onclick=()=>zoom(.8);$('zoom-out').onclick=()=>zoom(1.25);
$('import').onchange=async()=>{try{const file=$('import').files[0];if(!file||!tools.guardReplace())return;if(file.size>4*1024*1024)throw Error('Choose a JSON file under 4 MB.');await open(await file.text());}catch(e){status('Import rejected: '+e.message);}finally{$('import').value='';}};
$('export').onclick=()=>{if(!documentModel)return;const url=URL.createObjectURL(new Blob([documentModel.export()],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=(documentModel.map.name.replace(/[^a-z0-9_-]/gi,'-')||'design')+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
const coords=e=>{const r=canvas.getBoundingClientRect();return {x:e.clientX-r.left,y:e.clientY-r.top};};
canvas.addEventListener('pointerdown',e=>{if(![0,2].includes(e.button))return;const p=coords(e);drag={id:e.pointerId,button:e.button,...p,last:p,moved:false,selectArea:e.shiftKey&&e.button===0};canvas.setPointerCapture(e.pointerId);canvas.focus();});
canvas.addEventListener('pointermove',e=>{const cursor=coords(e);scene.foliageHover=scene.pick(cursor.x,cursor.y,canvas.clientWidth,canvas.clientHeight);dirty=true;if(!drag||drag.id!==e.pointerId)return;const p=coords(e);if(Math.hypot(p.x-drag.x,p.y-drag.y)>5)drag.moved=true;if(drag.moved&&!drag.selectArea){const a=scene.pick(drag.last.x,drag.last.y,canvas.clientWidth,canvas.clientHeight),b=scene.pick(p.x,p.y,canvas.clientWidth,canvas.clientHeight);if(a&&b){view.x+=a.x-b.x;view.y+=a.y-b.y;dirty=true;}}drag.last=p;});
canvas.addEventListener('pointerup',e=>{if(!drag||drag.id!==e.pointerId)return;const prior=drag,{moved,button}=drag;drag=null;if(canvas.hasPointerCapture(e.pointerId))canvas.releasePointerCapture(e.pointerId);if(moved&&prior.selectArea){const end=coords(e),a=scene.pick(prior.x,prior.y,canvas.clientWidth,canvas.clientHeight),b=scene.pick(end.x,end.y,canvas.clientWidth,canvas.clientHeight),cells=[],z=scene.options.level;if(a&&b){for(let y=Math.max(0,Math.round(Math.min(a.y,b.y)));y<=Math.min(documentModel.size-1,Math.round(Math.max(a.y,b.y)));y++)for(let x=Math.max(0,Math.round(Math.min(a.x,b.x)));x<=Math.min(documentModel.size-1,Math.round(Math.max(a.x,b.x)));x++)cells.push({x,y,z});const mix=treeCoverSelection(cells.map(p=>foliageAt(documentModel.map,p.x,p.y,z)));select({x:Math.round(a.x),y:Math.round(a.y),z,type:'tile',label:'Terrain selection',cells,data:{tiles:cells.length,treeCover:mix==='multiple'?'Multiple values':TREE_COVER[mix].label}});}}else if(!moved){const p=coords(e);if(button===2){const picked=scene.pickCharacter(p.x,p.y,canvas.clientWidth,canvas.clientHeight),fallback=inspect(p.x,p.y);characterMenu.menu.close();spotlightMenu.menu.close();if(picked||fallback?.type==='unit')characterMenu.show(picked||fallback.data,e.clientX,e.clientY);else {const light=scene.pickSpotlight(p.x,p.y,canvas.clientWidth,canvas.clientHeight);spotlightMenu.show(light?spotlightMenu.selectionFor(light):fallback,e.clientX,e.clientY);}}else select(inspect(p.x,p.y));}});canvas.addEventListener('pointercancel',()=>drag=null);
canvas.addEventListener('pointerleave',()=>{scene.foliageHover=null;dirty=true;});
canvas.addEventListener('wheel',e=>{e.preventDefault();zoom(Math.exp(e.deltaY*.001));},{passive:false});
document.addEventListener('keydown',e=>{
 if(document.querySelector('dialog[open]')||e.defaultPrevented||e.ctrlKey||e.metaKey||e.altKey||e.isComposing||e.target.isContentEditable||e.target.closest?.('input,textarea,select,[role="textbox"]'))return;
 if(['q','e'].includes(e.key.toLowerCase())){e.preventDefault();if(!e.repeat&&!drag&&!loading&&!tools.painting){rotateInspectionView(view,e.key.toLowerCase()==='q'?-1:1);$('camera').value=view.preset;dirty=true;}return;}
 const key=({w:'ArrowUp',a:'ArrowLeft',s:'ArrowDown',d:'ArrowRight'})[e.key.toLowerCase()]||e.key;
 if(!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','+','=','-','Home'].includes(key))return;
 e.preventDefault();
 if(key==='Home')home();else if(['+','='].includes(key))zoom(.8);else if(key==='-')zoom(1.25);
 else{
  const cx=canvas.clientWidth/2,cy=canvas.clientHeight/2,dx=key==='ArrowLeft'?-35:key==='ArrowRight'?35:0,dy=key==='ArrowUp'?-35:key==='ArrowDown'?35:0;
  const a=scene.pick(cx,cy,canvas.clientWidth,canvas.clientHeight),b=scene.pick(cx+dx,cy+dy,canvas.clientWidth,canvas.clientHeight);
  if(a&&b){view.x+=b.x-a.x;view.y+=b.y-a.y;dirty=true;}
 }
});
for(const item of PREVIEW_FOOTPRINTS){const li=document.createElement('li');li.textContent=item.name+' · '+item.tiles.join('×');$('cargo').append(li);}
new ResizeObserver(()=>dirty=true).observe(canvas);window.addEventListener('pagehide',()=>scene.dispose(),{once:true});
// Programmatic inspection shares the same opening and picking paths as the UI.
async function changed(){loading=true;try{const prior=selection,identity=selection?.data?.character?.id;await scene.update(documentModel);select(identity?documentModel.characterSelection(identity):prior?documentModel.inspect(prior.x,prior.y,prior.z,{mode:prior.type==='prop'?'prop':'auto'}):null);$('name').textContent=documentModel.map.name;$('counts').textContent=`${documentModel.size} × ${documentModel.size} · ${documentModel.map.guards.length} placed characters · ${documentModel.map.props.length} objects · ${documentModel.map.canopies?.length||0} decorative roofs`;dirty=true;}finally{loading=false;}}
async function switchWorkspace(mode){if(loading)return;const next=workspaces[mode]||new EditingDocument().open(JSON.stringify(mode==='block'?extractBlock(blockCanvas('New block')):blankMap('New design')));await open(next);}
characterMenu=new EditorCharacterMenu({canvas,scene,getDocument:()=>documentModel,getSelection:()=>selection,select,isBusy:()=>loading||tools?.busy,onStart:()=>spotlightMenu?.reset(),onEdit:()=>tools.sync(),onPropertyEdit:(id,patch)=>tools.run(()=>documentModel.updateCharacter(id,patch),'Character capability updated.'),status});
spotlightMenu=new EditorSpotlightMenu({menu:characterMenu.menu,canvas,scene,getDocument:()=>documentModel,getSelection:()=>selection,select,isBusy:()=>loading||tools?.busy,onStart:()=>characterMenu.reset(),onEdit:()=>tools.sync(),onLightEdit:(operation,message)=>tools.run(operation,message),status});
tools=installEditing({canvas,scene,getDocument:()=>documentModel,getSelection:()=>selection,open,changed,status,isLoading:()=>loading,switchWorkspace,hasUnsaved:()=>Object.values(workspaces).some(d=>d.changed),aimSpotlight:p=>spotlightMenu.start(p)});
characterMenu.bindTools();spotlightMenu.bindTools();
let currentPreset=null;
function rememberPreset(preset){currentPreset=preset;history.replaceState(null,'',location.pathname+presetSearch(preset));}
async function openPreset(preset){const map=await loadPreset(preset);await open(JSON.stringify(map));rememberPreset(preset);$('overview').click();status('Editing '+preset.id+'. Save creates a new variant in this configuration’s folder.');}
const sectorSave=installSectorSave({getDocument:()=>documentModel,status,getCurrent:()=>currentPreset,isLoading:()=>loading,onSaved:(result,context)=>{if(documentModel!==context.document)return;if(documentModel.revision===context.revision)documentModel.changed=false;rememberPreset({id:result.id,variant:result.variant,orientation:0,source:context.source});}});
const sectorPresets=installSectorPresets({openPreset,guardReplace:()=>tools.guardReplace(),getCurrent:()=>currentPreset});
$('quick-save-map').onclick=()=>documentModel?.map.sectorTemplate?.id&&!documentModel.block?sectorSave.show():$('save-map').click();
window.editor3d={open,select,changed,apply:command=>tools.apply(command),validate:()=>documentModel.validate(),export:()=>documentModel.export(),inspect:(x,y,z,options)=>documentModel.inspect(x,y,z,options),get document(){return documentModel;},get scene(){return scene;},get loading(){return loading;},get selection(){return selection;},view};
async function initialMap(){
 const params=new URLSearchParams(location.search),id=params.get('sectorTemplate');if(params.has('environmentPreview')){try{const key=params.get('environmentPreview');if(!/^\d{1,10}-\d{1,3}$/.test(key))throw Error('Invalid environment preview.');const {environmentPreviewMap,ENVIRONMENT_PREVIEW_KEY,environmentPreviewKey}=await import('./environment-preview.js'),data=JSON.parse(localStorage.getItem(ENVIRONMENT_PREVIEW_KEY+':'+key)||'null');if(data&&environmentPreviewKey(data.field,data.index)!==key)throw Error('Environment preview does not match its sector.');if(!data)throw Error('Open the environment preview from the overmap first.');await open(JSON.stringify(environmentPreviewMap(data.field,data.index)));Object.assign(view,{x:118,y:118,span:40});status('Environment sample · new biome plants and connected forest ground. Edit, export or playtest; this does not assign a campaign sector.');dirty=true;}catch(e){status('Environment preview unavailable: '+e.message);}return;}if(params.get('study')==='foliage-density'){const {foliageDensityFixture,FOLIAGE_DENSITIES}=await import('./foliage-density-fixture.js'),family=['temperate','jungle','snow','dry','wetlands'].includes(params.get('family'))?params.get('family'):'temperate',density=FOLIAGE_DENSITIES.includes(Number(params.get('density')))?Number(params.get('density')):65,growth=params.get('growth')==='thicket'?'thicket':'woodland';const mix=params.get('mix')||'brush-v1';const map=growth==='thicket'?(await import('./foliage-composition-fixture.js')).savedFoliageCompositionFixture(family,mix,density):foliageDensityFixture(family,density,growth);await open(JSON.stringify(map));Object.assign(view,{x:120,y:124,span:40});await changed();status('96 × 96 foliage fill · '+density+'% · '+growth+'. Edit, save or playtest this ordinary map.');return;}if(params.get('study')==='tutorial-intro'){const {tutorialIntroFixture}=await import('./tutorial-intro-fixture.js');await open(JSON.stringify(await tutorialIntroFixture()));Object.assign(view,{x:18,y:16,span:32});await changed();status('Tutorial intro rehearsal: guide, two sites and a searchable explosives crate. Assign these roles to objects in your plateau maps.');return;}if(params.get('study')==='dialogue'){const {dialogueFixture}=await import('./dialogue-fixture.js');await open(JSON.stringify(await dialogueFixture()));Object.assign(view,{x:13,y:12,span:22});await changed();status('Dialogue rehearsal · Nadia and the yard worker. Right-click in playtest to talk.');return;}if(params.get('study')==='hedges'){const {hedgeFixtureMap}=await import('./hedge-fixture.js');await open(JSON.stringify(hedgeFixtureMap()));Object.assign(view,{x:19,y:14,span:29});await changed();status('Joined hedges - Objects: short or tall. Drag to plant; leave a tile empty for a gate.');return;}if(params.get('study')==='climbing'){const {climbingFixture}=await import('./climbing-fixture.js');await open(JSON.stringify(climbingFixture()));Object.assign(view,{x:17,y:11,span:28});await changed();status('Climbing review · skill 100 ladder, 20 window, 40 roof, 90 wall. A rusty ladder stands to the south.');return;}if(params.get('study')==='biomes'){const {biomeFixture}=await import('./biome-fixture.js');await open(JSON.stringify(biomeFixture()));Object.assign(view,{x:123,y:117,span:53});status('Five environments · blocked terrain north, open woods south, raised ground on levels 2 and 3.');await changed();return;}if(params.get('study')==='stone-arches'){const {stoneArchFixture}=await import('./stone-arch-fixture.js');await open(JSON.stringify(stoneArchFixture()));Object.assign(view,{x:38,y:37,span:24});await changed();status('Small arch: footpath below, layer-2 walking route above. Objects > Scenery; R rotates. Large landmark placement waits for the deferred playable layer 4.');return;}if(params.get('study')==='factory-machines'){const {factoryMachineFixture}=await import('./factory-machine-fixture.js');await open(JSON.stringify(factoryMachineFixture(params.get('layout')||'review')));Object.assign(view,{x:25,y:25,span:39});await changed();status('Machines: 3 families × 4 directions, raised lathe, cover targets. Empty low-ceiling test at 40,16: mill and press must be rejected. R rotates scenery in four directions.');return;}if(params.get('study')==='scenery'){const {sceneryFixture}=await import('./scenery-fixture.js');await open(JSON.stringify(sceneryFixture()));Object.assign(view,{x:26,y:28,span:25});await changed();return;}if(params.get('study')==='strategic-sites'){const {strategicSiteFixture}=await import('./strategic-site-fixture.js');await open(JSON.stringify(strategicSiteFixture()));Object.assign(view,{x:33,y:33,span:40});await changed();return;}if(!id){await open(JSON.stringify(blankMap('New design')));return;}
 try{status('Opening sector map…');await openPreset({id,variant:params.get('variant')||'placeholder.json',orientation:Number(params.get('orientation')||0),source:params.get('library')==='folder'?'folder':'bundled'});}catch(e){status('Cannot open template: '+e.message);}
}
requestAnimationFrame(render);initialMap().then(()=>{if(new URLSearchParams(location.search).get('presets')==='1')sectorPresets.show();});
